import{_ as i,o as l,c as o,a2 as t}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"14.3 电动机控制线路实操要点","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-3-dian-dong-ji-kong-zhi-xian-lu-shi-cao-yao-dian.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-3-dian-dong-ji-kong-zhi-xian-lu-shi-cao-yao-dian.md","lastUpdated":1793096070000}'),n={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-3-dian-dong-ji-kong-zhi-xian-lu-shi-cao-yao-dian.md"};function s(e,a,r,h,c,g){return l(),o("div",null,[...a[0]||(a[0]=[t(`<h1 id="_14-3-电动机控制线路实操要点" tabindex="-1">14.3 电动机控制线路实操要点 <a class="header-anchor" href="#_14-3-电动机控制线路实操要点" aria-label="Permalink to &quot;14.3 电动机控制线路实操要点&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电动机控制线路接线(点动、自锁、正反转)是实操考核的重点项目。这一节从&quot;接线前—接线中—检查—试车&quot;四步梳理规范动作。</p><h2 id="一、接线前的准备" tabindex="-1">一、接线前的准备 <a class="header-anchor" href="#一、接线前的准备" aria-label="Permalink to &quot;一、接线前的准备&quot;">​</a></h2><ol><li><strong>看懂原理图</strong>:分清主电路和控制电路;</li><li><strong>核对元器件</strong>:接触器(KM)、热继电器(FR)、按钮(SB)、熔断器(FU)、断路器(QF)是否齐全完好;</li><li><strong>确认无电</strong>:操作前确认电源未接通(考核中一般由考官控制送电)。</li></ol><h2 id="二、接线步骤-以自锁控制为例" tabindex="-1">二、接线步骤(以自锁控制为例) <a class="header-anchor" href="#二、接线步骤-以自锁控制为例" aria-label="Permalink to &quot;二、接线步骤(以自锁控制为例)&quot;">​</a></h2><p><strong>主电路</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1L2L3 ─► QF ─► FU ─► KM主触点 ─► FR ─► M(电动机)</span></span></code></pre></div><p><strong>控制电路</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L ─► FU ─► 停止按钮SB(常闭) ─► 启动按钮SB(常开) ─► KM线圈 ─► FR常闭 ─► N</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    └── KM辅助常开(自锁触点) 与启动按钮并联</span></span></code></pre></div><p>接线要点:</p><ul><li>启动按钮与<strong>KM 辅助常开触点并联</strong>,实现自锁(松手不停);</li><li>停止按钮、FR 常闭触点<strong>串联</strong>在控制回路中;</li><li>导线<strong>颜色、编号</strong>规范,长短合理,不跨线飞线。</li></ul><h2 id="三、接好后必做的检查-考官最看重" tabindex="-1">三、接好后必做的检查(考官最看重) <a class="header-anchor" href="#三、接好后必做的检查-考官最看重" aria-label="Permalink to &quot;三、接好后必做的检查(考官最看重)&quot;">​</a></h2><ol><li><strong>查接线是否正确</strong>:对照原理图逐点核对;</li><li><strong>查自锁</strong>:启动按钮两端应并联 KM 辅助常开触点;</li><li><strong>查接触器、继电器型号</strong>:线圈电压与实际电源相符(如 380V/220V);</li><li><strong>查导线压接</strong>:端子压紧、不外露裸线;</li><li>用万用表<strong>粗测回路通断</strong>,确认无短路。</li></ol><h2 id="四、试车-送电-要点" tabindex="-1">四、试车(送电)要点 <a class="header-anchor" href="#四、试车-送电-要点" aria-label="Permalink to &quot;四、试车(送电)要点&quot;">​</a></h2><ul><li>试车前<strong>再次确认接线无误</strong>,请示考官后送电;</li><li>送电后先<strong>空载试车</strong>:按启动按钮,接触器吸合并自锁,电动机转动;</li><li>按停止按钮,电动机停止;</li><li>若电动机<strong>反转</strong>,说明相序接反(任调两根相线)。</li></ul><h2 id="五、正反转接线注意" tabindex="-1">五、正反转接线注意 <a class="header-anchor" href="#五、正反转接线注意" aria-label="Permalink to &quot;五、正反转接线注意&quot;">​</a></h2><ul><li>正转接触器 KM1、反转接触器 KM2;</li><li>反转:把<strong>两根相线对调</strong>接到电动机;</li><li><strong>互锁必须加</strong>(KM1 常闭串入 KM2 回路,反之亦然),防止两个接触器同时吸合短路。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 自锁=启动按钮并联 KM 辅助常开。</li><li>✅ 停止按钮、FR 常闭串在控制回路。</li><li>✅ 接完必须检查,再申请试车。</li><li>✅ 反转对调两相,正反转要互锁。</li><li>⚠️ 扣分点:未检查就送电、接线错乱飞线、自锁漏接——都要扣分。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>主电路管&quot;送电&quot;,控制电路管&quot;开关&quot;。</li><li>自锁靠并联辅助触点,保护靠串联常闭触点。</li><li>接线 → 检查 → 试车,三步缺一不可。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)自锁控制中,启动按钮应与接触器辅助常开触点并联。( )</li><li>(判断)控制回路中,停止按钮应串联在控制电路中。( )</li><li>(单选)电动机接线后反转,应()。 A. 加大电流　B. 任调两根相线　C. 减小负载　D. 换电机</li><li>(判断)正反转控制必须加互锁,防止两接触器同时吸合造成相间短路。( )</li><li>(判断)接好线路后,应认真检查核对无误,再申请送电试车。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。自锁触点(辅助常开)与启动按钮并联。</li><li><strong>√</strong>。停止按钮串联,按下断开回路。</li><li><strong>B</strong>。对调任意两根相线即反转。</li><li><strong>√</strong>。必须互锁防相间短路。</li><li><strong>√</strong>。先检查后试车。</li></ol></details>`,25)])])}const p=i(n,[["render",s]]);export{u as __pageData,p as default};
